custom_css:
/*
 * Theme: 铅雪青
 * Author: @jiuyi0204
 * Target: SillyTavern 1.14.0 / Text Completion / Default chat display
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 */

/* ===== src/tokens.css ===== */
/* Author: @jiuyi0204 | 铅雪青视觉令牌。未经许可禁止二改二传。 */
@font-face {
    font-family: "LXGW WenKai";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --theme-surface: #f8f7f2;
    --theme-surface-muted: #edf1ed;
    --theme-surface-disabled: #e2e9e5;
    --theme-surface-strong: #d2e0dc;
    --theme-text-primary: #263d42;
    --theme-text-secondary: #587176;
    --theme-text-disabled: #71888b;
    --theme-border: #688f92;
    --theme-border-soft: #a9bfbd;
    --theme-focus-ring: #4f8589;
    --theme-accent: #79a9a8;
    --theme-accent-strong: #3e7075;
    --theme-info: #4b7680;
    --theme-success: #49766d;
    --theme-warning: #906f45;
    --theme-error: #8e5860;
    --theme-opacity-disabled: 1;
    --theme-shadow: none;
    --theme-font-body: "LXGW WenKai", "Kaiti SC", STKaiti, KaiTi, "Noto Serif SC", serif;
    --theme-font-ui: "Noto Sans SC", "Microsoft YaHei UI", "Microsoft YaHei", sans-serif;
    --theme-font-display: "Zhuque Fangsong", "FangSong", STFangsong, "LXGW WenKai", serif;
    --theme-font-size-body: 1em;
    --theme-font-size-user: 1em;
    --theme-font-size-character: 1em;
    --theme-font-size-meta: 0.82em;
    --theme-font-size-input: 1em;
    --theme-avatar-user: 54px;
    --theme-avatar-character-width: 126px;
    --theme-avatar-character-height: 152px;
    --theme-avatar-gap: 18px;
    --theme-avatar-slot: calc(var(--theme-avatar-user) + var(--theme-avatar-gap));
    --st-theme-mobile-reading-width: 32em;
    --st-theme-mobile-reading-padding: 14px;
    --theme-radius-sm: 4px;
    --theme-radius-md: 8px;
    --theme-radius-lg: 14px;
    --theme-gap-xs: 4px;
    --theme-gap-sm: 8px;
    --theme-gap-md: 14px;
    --theme-gap-lg: 24px;
    --theme-speed: 150ms;
    --theme-mountain-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/114cce2e7623faf4c1a91462ef6f80af042910ee/assets/%E9%93%85%E9%9B%AA%E9%9D%92/mountain-contours.png");
    --theme-birds-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/114cce2e7623faf4c1a91462ef6f80af042910ee/assets/%E9%93%85%E9%9B%AA%E9%9D%92/bird-flight-divider.png");
}

@media (min-width: 701px) {
    :root {
        --theme-font-size-body: clamp(1.12rem, calc(0.74rem + 0.42vw), 1.4rem);
        --theme-font-size-user: clamp(1.12rem, calc(0.74rem + 0.42vw), 1.4rem);
        --theme-font-size-character: clamp(1.12rem, calc(0.74rem + 0.42vw), 1.4rem);
    }
}

/* ===== src/kernel/scrollbars.css ===== */
/* v6 滚动条内核：仅隐藏浏览器外观，保留滚轮、触控、键盘和容器滚动。 */

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
) {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
)::-webkit-scrollbar {
    width: 0;
    height: 0;
}

/* ===== src/chat-layout.css ===== */
/*
 * Author: @jiuyi0204
 * 铅雪青主聊天：连续寒地观测手记。真实姓名、时间、头像和消息数据均保留。
 */

body {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    font-family: var(--theme-font-ui);
}

#bg1,
#bg_custom {
    background-color: var(--theme-surface-muted);
    background-image:
        linear-gradient(90deg, var(--theme-border-soft) 1px, transparent 1px),
        linear-gradient(var(--theme-border-soft) 1px, transparent 1px);
    background-size: 44px 44px;
}

#chat {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border-inline: 2px solid var(--theme-border-soft);
}

#chat .mes {
    color: var(--theme-text-primary);
    background-color: transparent;
    border-bottom: 0;
}

#chat > .mes[is_system="false"] {
    position: relative;
    display: flex;
    flex: 0 0 auto;
    align-items: flex-start;
    gap: var(--theme-avatar-gap);
    padding: 22px clamp(18px, 4vw, 54px);
    block-size: auto;
    min-block-size: auto;
    max-block-size: none;
    overflow: visible;
}

#chat > .mes[is_system="false"] > .mesAvatarWrapper {
    position: static;
    inset: auto;
    z-index: auto;
    flex: 0 0 auto;
    align-self: flex-start;
    margin: 0;
    padding-bottom: 0;
    transform: none;
}

#chat > .mes[is_system="false"] > .mes_block {
    position: static;
    flex: 1 1 0;
    inline-size: auto;
    min-inline-size: 0;
    block-size: auto;
    min-block-size: auto;
    max-block-size: none;
    padding-inline-start: 10px;
    overflow-x: hidden;
    overflow-y: visible;
}

#chat > .mes[is_system="false"] > .mes_block > .mes_text {
    block-size: auto;
    min-block-size: auto;
    max-block-size: none;
}

#chat > .mes[is_user="true"] {
    border-bottom: 2px solid var(--theme-border-soft);
}

#chat > .mes[is_user="true"] > .mesAvatarWrapper {
    flex: 0 0 var(--theme-avatar-user);
    width: var(--theme-avatar-user);
}

#chat .mes[is_user="true"] .avatar,
#chat .mes[is_user="true"] .avatar img {
    width: var(--theme-avatar-user);
    height: var(--theme-avatar-user);
    border-radius: 50%;
}

#chat .mes[is_user="true"] .avatar {
    padding: 4px;
    background-color: var(--theme-surface-muted);
    border: 2px solid var(--theme-border-soft);
}

#chat .mes[is_user="true"] .ch_name {
    min-height: 0;
    margin-bottom: var(--theme-gap-xs);
}

#chat .mes[is_user="true"] .name_text {
    color: var(--theme-accent-strong);
    font-family: var(--theme-font-display);
    font-size: 1.16em;
    letter-spacing: 0.08em;
}

#chat .mes[is_user="true"] .timestamp {
    color: var(--theme-text-secondary);
    font-size: var(--theme-font-size-meta);
}

#chat .mes[is_user="false"][is_system="false"] {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto clamp(190px, 20vw, 250px);
    align-items: start;
    gap: 0;
    padding-block: clamp(24px, 3vw, 38px);
}

#chat > .mes[is_user="false"][is_system="false"]::before {
    content: "";
    grid-column: 1;
    grid-row: 2;
    align-self: stretch;
    width: 100%;
    min-width: 0;
    background: var(--theme-mountain-image) center / min(100%, 860px) auto no-repeat;
    pointer-events: none;
}

#chat > .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
    grid-column: 1;
    grid-row: 2;
    justify-self: center;
    align-self: center;
    z-index: 1;
    width: var(--theme-avatar-character-width);
}

#chat .mes[is_user="false"][is_system="false"] .avatar,
#chat .mes[is_user="false"][is_system="false"] .avatar img {
    width: var(--theme-avatar-character-width);
    height: var(--theme-avatar-character-height);
    border-radius: var(--theme-radius-sm);
}

#chat .mes[is_user="false"][is_system="false"] .avatar {
    padding: 5px;
    background-color: var(--theme-surface);
    border: 2px solid var(--theme-border);
}

#chat > .mes[is_user="false"][is_system="false"] > .mes_block {
    display: contents;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::before {
    content: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block > :not(.ch_name) {
    grid-column: 1;
    min-width: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    position: static;
    grid-column: 1;
    grid-row: 1;
    z-index: 2;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    align-items: end;
    min-height: 22px;
    margin-bottom: var(--theme-gap-sm);
    padding: 0;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name > .flex-container:first-child {
    grid-column: 1 / 4;
    grid-row: 1;
    display: block;
    min-width: 0;
    width: 100%;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name .alignItemsBaseline {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    align-items: end;
    min-width: 0;
    width: 100%;
    gap: 0;
    text-align: center;
}

#chat .mes[is_user="false"][is_system="false"] .name_text {
    grid-column: 2;
    grid-row: 1;
    justify-self: center;
    display: block;
    color: var(--theme-text-primary);
    font-family: var(--theme-font-display);
    max-width: min(52vw, 14ch);
    padding-inline: 0;
    font-size: clamp(2.2rem, 4.2vw, 4.5rem);
    font-weight: 400;
    line-height: 1.08;
    letter-spacing: 0.08em;
    text-indent: 0;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="false"][is_system="false"] .timestamp {
    grid-column: 1;
    grid-row: 1;
    justify-self: end;
    position: static;
    margin-inline-end: 16px;
    color: var(--theme-text-secondary);
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
    letter-spacing: 0.08em;
    padding-bottom: 2px;
    border-bottom: 1px solid var(--theme-border-soft);
}

#chat .mes[is_user="false"][is_system="false"] .mes_ghost {
    grid-column: 3;
    grid-row: 1;
    justify-self: start;
    align-self: end;
    margin-inline-start: 10px;
}

#chat .mes[is_user="false"][is_system="false"] .mesIDDisplay {
    width: max-content;
    margin: 8px auto 0;
    padding: 2px 8px;
    color: var(--theme-accent-strong);
    background-color: var(--theme-surface);
    border: 2px solid var(--theme-border-soft);
    border-radius: 999px;
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes[is_user="false"][is_system="false"] .mesIDDisplay::before {
    content: "楼层 ";
}

#chat .mes[is_user="false"][is_system="false"] .mes_buttons {
    grid-column: 3;
    grid-row: 1;
    justify-self: end;
    align-self: center;
    position: static;
    z-index: 3;
    flex: 0 0 auto;
    margin-inline-start: 0;
}

#chat .mes[is_system="true"] {
    margin: var(--theme-gap-md);
    padding: var(--theme-gap-md);
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border: 2px solid var(--theme-border-soft);
    border-radius: var(--theme-radius-md);
}

#chat .mes .mesIDDisplay,
#chat .mes .mes_timer,
#chat .mes .tokenCounterDisplay,
#chat .mes .swipes-counter {
    color: var(--theme-text-secondary);
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
}

#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--theme-text-secondary);
}

/* ===== src/full-text.css ===== */
/* Author: @jiuyi0204 | T03 诗性留白 + T06 文献排版。 */

#chat .mes_text {
    max-width: 74ch;
    margin-inline: auto;
    color: var(--theme-text-primary);
    font-family: var(--theme-font-body);
    font-size: var(--theme-font-size-body);
    font-weight: 400;
    line-height: 1.92;
    letter-spacing: 0.025em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    max-width: none;
    margin-inline: 0;
    font-size: var(--theme-font-size-user);
    line-height: 1.68;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    position: relative;
    z-index: 1;
    font-size: var(--theme-font-size-character);
}

#chat .mes[is_user="false"][is_system="false"] .mes_text::after {
    content: "";
    display: block;
    width: 100%;
    height: clamp(72px, 11vw, 104px);
    margin-block: 28px 12px;
    background: var(--theme-birds-image) center / contain no-repeat;
    pointer-events: none;
}

#chat .mes_text p {
    margin-block: 0 1.18em;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-display);
    font-weight: 400;
    line-height: 1.35;
    letter-spacing: 0.08em;
}

#chat .mes_text :is(strong, b) {
    color: var(--theme-accent-strong);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes_text :is(em, i) {
    color: var(--theme-text-secondary);
}

#chat .mes_text blockquote {
    margin: 1.4em 0;
    padding: 0.7em 1.1em;
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border-inline-start: 3px solid var(--theme-accent);
}

#chat .mes_text code {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-strong);
    border: 1px solid var(--theme-border-soft);
    border-radius: var(--theme-radius-sm);
    padding: 0.1em 0.35em;
    font-family: var(--theme-font-body);
}

#chat .mes_text pre {
    position: relative;
    max-width: 100%;
    margin: 1.4em 0;
    padding: 0;
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-muted);
    border: 2px solid var(--theme-border);
    border-radius: var(--theme-radius-md);
}

#chat .mes_text pre > code {
    display: block;
    max-width: 100%;
    padding: 1.1em 2.9em 1.1em 1.25em;
    overflow-x: auto;
    color: var(--theme-text-primary);
    background: transparent;
    border: 0;
    border-radius: 0;
    font-family: var(--theme-font-body);
    line-height: 1.68;
    white-space: pre;
}

#chat .mes_text pre > code.hljs {
    color: var(--theme-text-primary);
    background: transparent;
}

#chat .mes_text pre > code :is(.hljs-comment, .hljs-quote) {
    color: var(--theme-text-secondary);
    font-style: normal;
}

#chat .mes_text pre > code :is(.hljs-keyword, .hljs-selector-tag, .hljs-literal, .hljs-section, .hljs-link) {
    color: var(--theme-accent-strong);
}

#chat .mes_text pre > code :is(.hljs-string, .hljs-title, .hljs-name, .hljs-type, .hljs-attribute, .hljs-symbol, .hljs-bullet, .hljs-addition, .hljs-variable, .hljs-template-tag, .hljs-template-variable) {
    color: var(--theme-info);
}

#chat .mes_text pre > code :is(.hljs-number, .hljs-meta, .hljs-built_in, .hljs-builtin-name, .hljs-params) {
    color: var(--theme-warning);
}

#chat .mes_text .code-copy {
    top: 8px;
    right: 8px;
    width: 30px;
    height: 30px;
    margin: 0;
    color: var(--theme-surface);
    background-color: var(--theme-accent-strong);
    border: 1px solid var(--theme-text-primary);
    border-radius: var(--theme-radius-sm);
    opacity: 1;
}

#chat .mes_text .code-copy:hover,
#chat .mes_text .code-copy:focus-visible {
    color: var(--theme-surface);
    background-color: var(--theme-text-primary);
    opacity: 1;
}

#chat .mes_text .code-copy:focus-visible {
    outline: 2px solid var(--theme-focus-ring);
}

#chat .mes_text table {
    display: block;
    max-width: 100%;
    overflow-x: auto;
    border-collapse: collapse;
}

#chat .mes_text :is(th, td) {
    padding: 0.55em 0.75em;
    border: 1px solid var(--theme-border-soft);
}

#chat .mes_text hr {
    width: min(72%, 520px);
    margin: 2em auto;
    border: 0;
    border-top: 2px solid var(--theme-border);
}

#chat .mes_text a {
    color: var(--theme-accent-strong);
    text-decoration-color: var(--theme-accent);
}

#chat .mes_text img {
    max-width: 100%;
    height: auto;
    border: 2px solid var(--theme-border-soft);
    border-radius: var(--theme-radius-sm);
}

/* ===== src/windows/top-bar.css ===== */
/* W02 顶栏：只修改入口触发器，不改 .drawer 父级几何。 */

#top-settings-holder {
    align-items: center;
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > [class~="drawer-toggle"] {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: var(--topBarBlockSize);
    min-width: 36px;
    min-height: 36px;
    margin-inline: 0;
    padding: 0;
    border-radius: 0;
    transition: color var(--theme-speed), background-color var(--theme-speed), border-color var(--theme-speed);
}

#top-settings-holder > :is(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) > [class~="drawer-toggle"] > [class~="drawer-icon"] {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    block-size: 100%;
    padding: 0;
    font-size: 1.05em;
}

/* ===== src/windows/input.css ===== */
/* W03 输入区：保留菜单、魔法棒、附件、继续、发送与停止节点。 */

#send_form {
    min-height: 58px;
    padding: 6px 8px;
    border-radius: var(--theme-radius-sm);
}

#send_form #nonQRFormItems {
    align-items: center;
    gap: 6px;
}

#send_form #leftSendForm,
#send_form #rightSendForm {
    flex: 0 0 auto;
    gap: 4px;
}

#send_textarea {
    min-width: 0;
    min-height: 42px;
    max-height: 160px;
    padding: 9px 12px;
    resize: vertical;
    font-family: var(--theme-font-body);
    font-size: var(--theme-font-size-input);
    line-height: 1.55;
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop,
#mes_continue,
#mes_impersonate,
#send_form .stscript_btn {
    flex: 0 0 40px;
    width: 40px;
    height: 40px;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
}

#send_but,
#mes_stop {
    border-radius: var(--theme-radius-sm);
}

#send_form .file_attached {
    border-radius: var(--theme-radius-sm);
}

/* ===== src/windows/text-completion.css ===== */
/* W04 文本补全参数。 */

#left-nav-panel {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border-color: var(--theme-border-soft);
}

#left-nav-panel :is(h2, h3, h4) {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#left-nav-panel .range-block,
#left-nav-panel .completion_preset_block {
    margin-block: 4px;
    padding: 6px 8px;
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-sm);
}

#left-nav-panel .inline-drawer {
    margin-block: 4px;
    padding: 0;
    background: transparent;
    border: 0;
}

#textgenerationwebui_api-settings {
    gap: var(--theme-gap-sm);
}

/* ===== src/windows/api.css ===== */
/* W05 API 连接。 */

#rm_api_block {
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    border-color: var(--theme-border-soft);
}

#rm_api_block :is(h2, h3, h4) {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
}

