    border-color: var(--theme-border-soft);
}

#AdvancedFormatting :is(h2, h3, h4) {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#AdvancedFormatting :is(
    label,
    .checkbox_label,
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
    textarea,
    select,
    .text_pole
) {
    color: var(--theme-text-primary);
    text-shadow: none;
    filter: none;
}

#AdvancedFormatting :is(
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
    textarea,
    select,
    .text_pole
) {
    background: var(--theme-surface);
    border-color: var(--theme-border);
    opacity: 1;
    box-shadow: none;
}

#AdvancedFormatting :is(input, textarea)::placeholder {
    color: var(--theme-text-secondary);
    opacity: 1;
}

#AdvancedFormatting :is(.menu_button, .right_menu_button):not(.disabled):not([disabled]):not([aria-disabled="true"]) {
    color: var(--theme-text-primary);
    background: var(--theme-surface-muted);
    border-color: var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#AdvancedFormatting :is(.menu_button, .right_menu_button):not(.disabled):not([disabled]):not([aria-disabled="true"]):hover {
    color: var(--theme-text-primary);
    background: var(--theme-surface-strong);
    border-color: var(--theme-accent-strong);
}

#AdvancedFormatting :is(.menu_button, .right_menu_button):focus-visible,
#AdvancedFormatting :is(
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
    textarea,
    select,
    .text_pole
):focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

#AdvancedFormatting :is(.menu_button, .right_menu_button):is(:active, .active, .toggleEnabled, [aria-pressed="true"]):not(.disabled):not([disabled]) {
    color: var(--theme-surface);
    background: var(--theme-accent-strong);
    border-color: var(--theme-accent-strong);
}

/* 官方 Chat Completion 规则在此处叠加 opacity 与 grayscale；改用可读的语义色，不再整体合成变淡。 */
#AdvancedFormatting [data-cc-null] {
    color: var(--theme-text-secondary);
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none;
}

#AdvancedFormatting [data-cc-null] :is(h2, h3, h4, label, .checkbox_label, small) {
    color: var(--theme-text-secondary);
}

#AdvancedFormatting [data-cc-null] :is(
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
    textarea,
    select,
    .text_pole,
    .menu_button,
    .right_menu_button
) {
    color: var(--theme-text-secondary);
    background: var(--theme-surface-muted);
    border-color: var(--theme-border-soft);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

/* Master 导入/导出仍是可用操作，不继承 data-cc-null 的无效态外观。 */
#AdvancedFormatting :is(#af_master_import, #af_master_export) {
    color: var(--theme-text-primary);
    background: var(--theme-surface-muted);
    border-color: var(--theme-border);
    cursor: pointer;
    opacity: 1 !important;
    filter: none !important;
    box-shadow: none;
    text-shadow: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export) :is(i, span) {
    color: inherit;
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export):hover {
    color: var(--theme-text-primary);
    background: var(--theme-surface-strong);
    border-color: var(--theme-accent-strong);
}

#AdvancedFormatting :is(#af_master_import, #af_master_export):focus-visible {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

#AdvancedFormatting :is(#af_master_import, #af_master_export):active {
    color: var(--theme-surface);
    background: var(--theme-accent-strong);
    border-color: var(--theme-accent-strong);
}

/* 真正 disabled 保留独立的文字、表面与光标差异，不再依赖 brightness 或低透明度。 */
#AdvancedFormatting :is(
    input:not([type="checkbox"]):not([type="radio"]):not([type="range"]),
    textarea,
    select,
    button
):disabled,
#AdvancedFormatting :is(.menu_button, .right_menu_button):is(.disabled, [disabled], [aria-disabled="true"]) {
    color: var(--theme-text-disabled);
    background: var(--theme-surface-disabled);
    border-color: var(--theme-border-soft);
    cursor: not-allowed;
    opacity: 1 !important;
    filter: none !important;
    box-shadow: none;
    text-shadow: none;
}

#AdvancedFormatting :is(label, .checkbox_label):has(:disabled),
#AdvancedFormatting :is(label, .checkbox_label).disabled {
    color: var(--theme-text-disabled);
}

#AdvancedFormatting :is(input, textarea):disabled::placeholder {
    color: var(--theme-text-disabled);
    opacity: 1;
}

