/* ===== src/windows/mobile.css ===== */
/* W14 默认 390px 独立母版；只覆盖聊天与输入，不改抽屉父级几何。 */

@media (max-width: 700px) and (hover: none) and (pointer: coarse) {
    :root {
        --theme-avatar-user: 44px;
        --theme-avatar-character-width: 96px;
        --theme-avatar-character-height: 116px;
        --theme-avatar-gap: 12px;
    }

    #chat > .mes[is_user="true"] {
        padding: 18px 14px;
    }

    #chat > .mes[is_system="false"] {
        display: flex;
        flex: 0 0 auto;
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
        block-size: auto;
        min-block-size: auto;
        max-block-size: none;
        overflow: visible;
    }

    #chat > .mes[is_system="false"] > .mesAvatarWrapper {
        position: static;
        z-index: auto;
        inset: auto;
        flex: 0 0 auto;
        transform: none;
        align-self: center;
        margin-inline: auto;
        order: 0;
    }

    #chat > .mes[is_system="false"] > .mes_block {
        position: static;
        flex: 0 0 auto;
        inline-size: 100%;
        min-inline-size: 0;
        block-size: auto;
        min-block-size: auto;
        max-block-size: none;
        overflow-y: visible;
        order: 1;
    }

    #chat > .mes[is_system="false"] > .mes_block > .mes_text {
        inline-size: min(100%, var(--st-theme-mobile-reading-width));
        max-inline-size: 100%;
        block-size: auto;
        min-block-size: auto;
        max-block-size: none;
        margin-inline: auto !important;
        padding-inline: var(--st-theme-mobile-reading-padding) !important;
        box-sizing: border-box;
    }

    #chat > .mes[is_user="false"][is_system="false"] {
        display: grid;
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: auto 156px;
        align-items: start;
        gap: 0;
        padding: 28px 16px 34px;
    }

    #chat > .mes[is_user="false"][is_system="false"]::before {
        grid-column: 1;
        grid-row: 2;
        background-position: center;
        background-size: 100% auto;
    }

    #chat > .mes[is_user="false"][is_system="false"] > .mesAvatarWrapper {
        grid-column: 1;
        grid-row: 2;
        justify-self: center;
        align-self: center;
        order: initial;
    }

    #chat .mes[is_user="false"][is_system="false"] .name_text {
        max-width: min(100%, 24ch);
        padding-inline: 0;
        font-size: clamp(1.35em, 7vw, 1.8em);
        line-height: 1.2;
        letter-spacing: 0.08em;
        text-indent: 0;
    }

    #chat > .mes[is_user="false"][is_system="false"] > .mes_block {
        display: contents;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name {
        grid-column: 1;
        grid-row: 1;
        min-height: 22px;
        margin-bottom: 8px;
        padding: 0;
        box-sizing: border-box;
    }

    #chat .mes[is_user="false"][is_system="false"] .timestamp {
        position: static;
        display: inline-block;
        z-index: 2;
        width: max-content;
        max-inline-size: 100%;
        margin: 0 10px 0 0;
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
    }

    #chat .mes[is_user="false"][is_system="false"] .mesIDDisplay {
        margin-top: 6px;
        padding: 1px 6px;
    }

    #chat .mes_text {
        line-height: 1.78;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_text {
        text-align: justify;
        text-justify: inter-ideograph;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_text::after {
        height: 48px;
        margin-block: 14px 0;
    }

    #chat .mes_text pre {
        box-sizing: border-box;
        width: 100%;
        min-width: 0;
        max-width: 100%;
        margin-block: 1em;
        overflow-x: hidden;
    }

    #chat .mes_text pre > code {
        box-sizing: border-box;
        width: 100%;
        min-width: 0;
        max-width: 100%;
        padding: 0.9em 2.6em 0.9em 1em;
        overflow-x: hidden;
        font-size: 0.92em;
        white-space: pre-wrap;
        overflow-wrap: anywhere;
        word-break: break-word;
    }

    #top-settings-holder > :is(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) > [class~="drawer-toggle"] {
        min-width: 30px;
        min-height: 30px;
        margin-inline: 0;
        border-radius: 0;
    }

    #left-nav-panel .range-block,
    #left-nav-panel .completion_preset_block,
    #rm_extensions_block :is(.extension_block, .extension-item) {
        margin-block: 3px;
        padding: 5px 7px;
    }

    #left-nav-panel .inline-drawer,
    #rm_extensions_block .inline-drawer {
        margin-block: 3px;
    }

    #send_form {
        min-height: 52px;
        padding: 4px 5px;
    }

    #send_form #nonQRFormItems {
        display: flex;
        flex-flow: row nowrap;
        align-items: center;
        width: 100%;
        min-width: 0;
        gap: 4px;
    }

    #send_form #leftSendForm {
        order: 1;
        display: flex;
        flex: 0 0 auto;
        flex-flow: row nowrap;
        align-items: center;
        width: auto;
        min-width: 0;
        gap: 4px;
    }

    #send_form #rightSendForm {
        order: 3;
        display: flex;
        flex: 0 0 36px;
        flex-flow: row nowrap;
        align-items: center;
        justify-content: center;
        width: 36px;
        min-width: 36px;
        gap: 0;
    }

    #options_button,
    #extensionsMenuButton,
    #send_but,
    #mes_stop,
    #mes_continue,
    #mes_impersonate,
    #send_form .stscript_btn {
        flex-basis: 36px;
        width: 36px;
        height: 36px;
    }

    #send_textarea {
        order: 2;
        flex: 1 1 0;
        width: 0;
        min-width: 0;
        min-height: 38px;
        max-height: 132px;
        padding: 7px 9px;
        font-size: clamp(13px, 3.6vw, 15px);
        line-height: 1.45;
    }

    #send_textarea::placeholder {
        font-size: inherit !important;
    }
}

